package cli

import "testing"

func TestHasClaudeHostCredentials(t *testing.T) {
	t.Run("no credentials", func(t *testing.T) {
		t.Setenv("ANTHROPIC_API_KEY", "")
		t.Setenv("CLAUDE_CODE_OAUTH_TOKEN", "")

		if hasClaudeHostCredentials() {
			t.Fatal("expected no Claude host credentials")
		}
	})

	t.Run("anthropic api key", func(t *testing.T) {
		t.Setenv("ANTHROPIC_API_KEY", "test-key")
		t.Setenv("CLAUDE_CODE_OAUTH_TOKEN", "")

		if !hasClaudeHostCredentials() {
			t.Fatal("expected ANTHROPIC_API_KEY to count as Claude host credentials")
		}
	})

	t.Run("oauth token", func(t *testing.T) {
		t.Setenv("ANTHROPIC_API_KEY", "")
		t.Setenv("CLAUDE_CODE_OAUTH_TOKEN", "test-token")

		if !hasClaudeHostCredentials() {
			t.Fatal("expected CLAUDE_CODE_OAUTH_TOKEN to count as Claude host credentials")
		}
	})
}

package cli

import (
	"slices"
	"testing"

	"dv/internal/config"
)

func init() {
	// Register my-agent as a built-in rule so tests can exercise the
	// defaults-only config override path without coupling to a real agent's flags.
	agentRules["my-agent"] = agentRule{
		interactive: func() []string { return []string{"my-agent"} },
		withPrompt:  func(p string) []string { return []string{"my-agent", "-p", p} },
		defaults:    []string{"--default-flag"},
	}
	agentAliasMap["my-agent"] = "my-agent"
}

func TestBuildAgentArgsCodexIncludesSearchBeforeExec(t *testing.T) {
	args := buildAgentArgs("codex", "abc")
	if len(args) < 4 {
		t.Fatalf("unexpected args: %#v", args)
	}
	if args[0] != "codex" {
		t.Fatalf("first arg = %q", args[0])
	}
	// Ensure defaults are injected before subcommand 'exec'
	idxExec := -1
	idxSearch := -1
	for i, a := range args {
		if a == "exec" {
			idxExec = i
		}
		if a == "--search" {
			idxSearch = i
		}
	}
	if idxExec == -1 || idxSearch == -1 || idxSearch > idxExec {
		t.Fatalf("expected --search before exec in %#v", args)
	}
}

func TestBuildAgentArgsCodexPromptAtEnd(t *testing.T) {
	args := buildAgentArgs("codex", "abc")
	if got := args[len(args)-1]; got != "abc" {
		t.Fatalf("last arg = %q, want prompt", got)
	}
}

func TestBuildAgentArgsGrokUsesSinglePromptAndYolo(t *testing.T) {
	args := buildAgentArgs("grok", "hello")
	want := []string{"grok", "--yolo", "-p", "hello"}
	if !slices.Equal(args, want) {
		t.Fatalf("args = %#v, want %#v", args, want)
	}
}

func TestBuildAgentInteractiveGrokUsesYolo(t *testing.T) {
	args := buildAgentInteractive("grok")
	want := []string{"grok", "--yolo"}
	if !slices.Equal(args, want) {
		t.Fatalf("args = %#v, want %#v", args, want)
	}
}

func TestBuildAgentArgsAgyUsesPrintAndSkipsPermissions(t *testing.T) {
	args := buildAgentArgs("agy", "hello")
	want := []string{"agy", "--dangerously-skip-permissions", "-p", "hello"}
	if !slices.Equal(args, want) {
		t.Fatalf("args = %#v, want %#v", args, want)
	}
}

func TestBuildAgentInteractiveAgyAliasSkipsPermissions(t *testing.T) {
	agent := resolveAgentAlias("antigravity")
	if agent != "agy" {
		t.Fatalf("agent = %q, want agy", agent)
	}
	args := buildAgentInteractive(agent)
	want := []string{"agy", "--dangerously-skip-permissions"}
	if !slices.Equal(args, want) {
		t.Fatalf("args = %#v, want %#v", args, want)
	}
}

func TestBuildAgentArgsTermLLMPutsDeveloperAndYoloAfterAsk(t *testing.T) {
	args := buildAgentArgs("term-llm", "hello")
	want := []string{"term-llm", "ask", "@developer", "--yolo", "hello"}
	if len(args) != len(want) {
		t.Fatalf("args = %#v, want %#v", args, want)
	}
	for i := range want {
		if args[i] != want[i] {
			t.Fatalf("args = %#v, want %#v", args, want)
		}
	}
}

func TestBuildCustomAgentArgs(t *testing.T) {
	cfg := config.Config{Agents: map[string]config.AgentConfig{
		"my-agent": {
			Command:         "custom-cli",
			Args:            []string{"run"},
			PromptArgs:      []string{"--prompt"},
			InteractiveArgs: []string{"--interactive"},
			Aliases:         []string{"ma"},
		},
	}}

	agent := resolveAgentAliasWithConfig(cfg, "ma")
	if agent != "my-agent" {
		t.Fatalf("expected alias to resolve to my-agent, got %q", agent)
	}

	promptArgs := buildAgentArgsWithConfig(cfg, agent, "hello")
	wantPrompt := []string{"custom-cli", "run", "--prompt", "hello"}
	if len(promptArgs) != len(wantPrompt) {
		t.Fatalf("expected %v, got %v", wantPrompt, promptArgs)
	}
	for i := range wantPrompt {
		if promptArgs[i] != wantPrompt[i] {
			t.Fatalf("expected %v, got %v", wantPrompt, promptArgs)
		}
	}

	interactiveArgs := buildAgentInteractiveWithConfig(cfg, agent)
	wantInteractive := []string{"custom-cli", "run", "--interactive"}
	if len(interactiveArgs) != len(wantInteractive) {
		t.Fatalf("expected %v, got %v", wantInteractive, interactiveArgs)
	}
	for i := range wantInteractive {
		if interactiveArgs[i] != wantInteractive[i] {
			t.Fatalf("expected %v, got %v", wantInteractive, interactiveArgs)
		}
	}

	rawArgs := buildAgentRawWithConfig(cfg, agent, []string{"--help"})
	wantRaw := []string{"custom-cli", "run", "--help"}
	if len(rawArgs) != len(wantRaw) {
		t.Fatalf("expected %v, got %v", wantRaw, rawArgs)
	}
	for i := range wantRaw {
		if rawArgs[i] != wantRaw[i] {
			t.Fatalf("expected %v, got %v", wantRaw, rawArgs)
		}
	}
}

func TestBuiltinAgentConfigDefaultsOverride(t *testing.T) {
	overrideDefaults := []string{"--other-flag"}
	cfg := config.Config{Agents: map[string]config.AgentConfig{
		"my-agent": {
			Defaults: &overrideDefaults,
		},
	}}

	args := buildAgentArgsWithConfig(cfg, "my-agent", "hello")
	want := []string{"my-agent", "--other-flag", "-p", "hello"}
	if !slices.Equal(args, want) {
		t.Fatalf("args = %#v, want %#v", args, want)
	}

	interactive := buildAgentInteractiveWithConfig(cfg, "my-agent")
	wantInteractive := []string{"my-agent", "--other-flag"}
	if !slices.Equal(interactive, wantInteractive) {
		t.Fatalf("interactive = %#v, want %#v", interactive, wantInteractive)
	}
}

func TestBuiltinAgentConfigDefaultsClear(t *testing.T) {
	empty := []string{}
	cfg := config.Config{Agents: map[string]config.AgentConfig{
		"my-agent": {
			Defaults: &empty,
		},
	}}

	args := buildAgentArgsWithConfig(cfg, "my-agent", "hello")
	want := []string{"my-agent", "-p", "hello"}
	if !slices.Equal(args, want) {
		t.Fatalf("args = %#v, want %#v", args, want)
	}
}

func TestBuiltinAgentConfigDefaultsNotSetUsesBuiltin(t *testing.T) {
	cfg := config.Config{Agents: map[string]config.AgentConfig{
		"my-agent": {
			Env: []string{"MY_VAR"},
		},
	}}

	args := buildAgentArgsWithConfig(cfg, "my-agent", "hello")
	want := buildAgentArgs("my-agent", "hello")
	if !slices.Equal(args, want) {
		t.Fatalf("args = %#v, want %#v", want, args)
	}
}

func TestCustomAgentOverridesBuiltinAlias(t *testing.T) {
	cfg := config.Config{Agents: map[string]config.AgentConfig{
		"my-agent": {
			Command: "custom-cli",
			Aliases: []string{"tl"},
		},
	}}

	agent := resolveAgentAliasWithConfig(cfg, "tl")
	if agent != "my-agent" {
		t.Fatalf("expected alias to resolve to my-agent, got %q", agent)
	}
	args := buildAgentArgsWithConfig(cfg, agent, "hello")
	want := []string{"custom-cli", "hello"}
	if len(args) != len(want) {
		t.Fatalf("expected %v, got %v", want, args)
	}
	for i := range want {
		if args[i] != want[i] {
			t.Fatalf("expected %v, got %v", want, args)
		}
	}
}

package cli

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"sync/atomic"
	"testing"
	"time"

	"dv/internal/config"
	"dv/internal/xdg"

	"github.com/spf13/cobra"
)

func setupHostnameReconcileTest(t *testing.T) (*cobra.Command, string, string, *atomic.Bool) {
	t.Helper()
	t.Setenv("XDG_CONFIG_HOME", t.TempDir())
	t.Setenv("XDG_RUNTIME_DIR", t.TempDir())
	t.Setenv("XDG_DATA_HOME", t.TempDir())
	t.Setenv("DV_AGENT", "")
	var fail atomic.Bool
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if fail.Load() {
			http.Error(w, "unavailable", 503)
			return
		}
		if r.Method == "DELETE" {
			w.WriteHeader(204)
		} else {
			w.WriteHeader(201)
		}
	}))
	t.Cleanup(server.Close)
	bin := t.TempDir()
	log := filepath.Join(t.TempDir(), "scripts")
	t.Setenv("DV_TEST_SCRIPT_LOG", log)
	t.Setenv("DV_TEST_PRIMARY", "forum.dev.home.arpa")
	script := `#!/bin/sh
case "$1" in
ps) echo forum;;
inspect) case "$*" in
 *Config.Labels*) printf '{"com.dv.local-proxy.host":"%s","com.dv.local-proxy.target-port":"3001","com.dv.local-proxy.container-port":"3000"}\n' "$DV_TEST_PRIMARY";;
 *NetworkSettings*) echo 127.0.0.2;;
 *Config.Env*) echo '["PROXY_ALIASES_FILE=/etc/local-proxy/aliases/aliases.json"]';;
 *) exit 1;;
 esac;;
rm) exit 0;;
exec) cat >> "$DV_TEST_SCRIPT_LOG"; if [ "${DV_TEST_FAIL_EXEC:-}" = 1 ]; then echo 'service unavailable' >&2; exit 1; fi;;
*) exit 1;;
esac
`
	if err := os.WriteFile(filepath.Join(bin, "docker"), []byte(script), 0o755); err != nil {
		t.Fatal(err)
	}
	t.Setenv("PATH", bin+string(os.PathListSeparator)+os.Getenv("PATH"))
	dir, err := xdg.ConfigDir()
	if err != nil {
		t.Fatal(err)
	}
	cfg := config.Default()
	cfg.LocalProxy.Enabled = true
	cfg.LocalProxy.Hostname = "dev.home.arpa"
	_, port, _ := net.SplitHostPort(server.Listener.Addr().String())
	cfg.LocalProxy.APIPort, _ = strconv.Atoi(port)
	cfg.ContainerImages["forum"] = "discourse"
	if err := config.Save(dir, cfg); err != nil {
		t.Fatal(err)
	}
	cmd := &cobra.Command{}
	cmd.SetContext(context.Background())
	cmd.SetOut(&bytes.Buffer{})
	cmd.SetErr(&bytes.Buffer{})
	return cmd, dir, log, &fail
}

func TestHostnamePartialFailureCanBeRetried(t *testing.T) {
	cmd, dir, log, fail := setupHostnameReconcileTest(t)
	fail.Store(true)
	if err := runHostname(cmd, "add", []string{"forum", "customers"}); err == nil || !strings.Contains(err.Error(), "not fully applied") {
		t.Fatalf("add: %v", err)
	}
	if _, err := os.Stat(log); err != nil {
		t.Fatal("application sync was skipped after proxy failure")
	}
	fail.Store(false)
	if err := runHostname(cmd, "add", []string{"forum", "customers"}); err != nil {
		t.Fatal(err)
	}
	fail.Store(true)
	if err := runHostname(cmd, "remove", []string{"forum", "customers"}); err == nil {
		t.Fatal("reported success on failed live removal")
	}
	cfg, _ := config.LoadOrCreate(dir)
	if len(cfg.HostnameAliases["forum"]) != 0 || len(cfg.HostnameRemovals["forum"]) != 1 {
		t.Fatalf("missing cleanup journal: %+v", cfg.HostnameRemovals)
	}
	if err := checkPrimaryHostname(cfg, "customers"); err == nil {
		t.Fatal("allowed primary to steal pending cleanup route")
	}
	fail.Store(false)
	if err := runHostname(cmd, "remove", []string{"forum", "customers"}); err != nil {
		t.Fatal(err)
	}
	if err := runHostname(cmd, "remove", []string{"forum", "customers"}); err != nil {
		t.Fatalf("remove not idempotent: %v", err)
	}
	cfg, _ = config.LoadOrCreate(dir)
	if len(cfg.HostnameRemovals) != 0 {
		t.Fatalf("cleanup remains: %+v", cfg.HostnameRemovals)
	}
}

func TestHostnamePrimaryUsesRecordedIdentity(t *testing.T) {
	cmd, _, log, _ := setupHostnameReconcileTest(t)
	t.Setenv("DV_TEST_PRIMARY", "forum.old.home.arpa")
	if err := runHostname(cmd, "add", []string{"forum", "customers"}); err != nil {
		t.Fatal(err)
	}
	data, err := os.ReadFile(log)
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(data), "forum.old.home.arpa,customers.dev.home.arpa") {
		t.Fatalf("primary identity changed: %s", data)
	}
}

func TestHostnameLifecycleFailureWarnsWithoutBlocking(t *testing.T) {
	cmd, dir, _, _ := setupHostnameReconcileTest(t)
	cfg, _ := config.LoadOrCreate(dir)
	cfg.HostnameAliases = map[string][]string{"forum": {"customers.dev.home.arpa"}}
	if err := config.Save(dir, cfg); err != nil {
		t.Fatal(err)
	}
	t.Setenv("DV_TEST_FAIL_EXEC", "1")
	var output bytes.Buffer
	cmd.SetErr(&output)
	syncContainerHostnamesBestEffort(cmd, cfg, "forum")
	if !strings.Contains(output.String(), "Warning:") || !strings.Contains(output.String(), "service unavailable") {
		t.Fatal(output.String())
	}
	cfg.LocalProxy.Enabled = false
	if err := checkPrimaryHostname(cfg, "customers"); err != nil {
		t.Fatal("disabled proxy blocked start", err)
	}
}

func TestRenameSynchronizesManagedHostnameEnvironment(t *testing.T) {
	cmd, dir, log, _ := setupHostnameReconcileTest(t)
	if err := config.Update(dir, func(cfg *config.Config) error {
		cfg.HostnameAliases = map[string][]string{"forum": {"customers.dev.home.arpa"}}
		return nil
	}); err != nil {
		t.Fatal(err)
	}
	oldExists, oldRename := renameDockerExists, renameDockerRenameContext
	renameDockerExists = func(name string) bool { return name == "forum" }
	renameDockerRenameContext = func(context.Context, string, string, io.Writer, io.Writer) error { return nil }
	t.Cleanup(func() { renameDockerExists, renameDockerRenameContext = oldExists, oldRename })
	if err := runRename(cmd, "forum", "shop"); err != nil {
		t.Fatal(err)
	}
	data, err := os.ReadFile(log)
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(data), "shop.dev.home.arpa,customers.dev.home.arpa") {
		t.Fatalf("renamed primary missing from runtime settings: %s", data)
	}
}

func TestHostnameCleanupStaleSnapshotDoesNotPanic(t *testing.T) {
	_, dir, _, _ := setupHostnameReconcileTest(t)
	if err := config.Update(dir, func(cfg *config.Config) error {
		queueHostnameRemovals(cfg, "forum", "customers.dev.home.arpa")
		return nil
	}); err != nil {
		t.Fatal(err)
	}
	stale, _ := config.LoadOrCreate(dir)
	for i := 0; i < 2; i++ {
		if err := cleanupHostnameRoutes(dir, stale, "forum"); err != nil {
			t.Fatal(err)
		}
	}
}

func TestHostnameReAddCancelsPendingRemoval(t *testing.T) {
	cmd, dir, _, fail := setupHostnameReconcileTest(t)
	if err := runHostname(cmd, "add", []string{"forum", "customers"}); err != nil {
		t.Fatal(err)
	}
	fail.Store(true)
	if err := runHostname(cmd, "remove", []string{"forum", "customers"}); err == nil {
		t.Fatal("expected pending removal")
	}
	fail.Store(false)
	if err := runHostname(cmd, "add", []string{"forum", "customers"}); err != nil {
		t.Fatal(err)
	}
	cfg, _ := config.LoadOrCreate(dir)
	if len(cfg.HostnameRemovals["forum"]) != 0 || len(cfg.HostnameAliases["forum"]) != 1 {
		t.Fatal("re-add retained removal intent")
	}
}

func TestHostnameCleanupAfterExternalContainerRemoval(t *testing.T) {
	cmd, dir, _, _ := setupHostnameReconcileTest(t)
	if err := config.Update(dir, func(cfg *config.Config) error { queueHostnameRemovals(cfg, "gone", "gone.dev.home.arpa"); return nil }); err != nil {
		t.Fatal(err)
	}
	bin := t.TempDir()
	stub := "#!/bin/sh\ncase \"$1\" in inspect) exit 1;; ps) case \"$*\" in *dv-local-proxy*) echo proxy;; esac;; *) exit 1;; esac\n"
	if err := os.WriteFile(filepath.Join(bin, "docker"), []byte(stub), 0o755); err != nil {
		t.Fatal(err)
	}
	t.Setenv("PATH", bin+string(os.PathListSeparator)+os.Getenv("PATH"))
	for i := 0; i < 2; i++ {
		if err := runHostname(cmd, "remove", []string{"gone", "gone"}); err != nil {
			t.Fatal(err)
		}
	}
	cfg, _ := config.LoadOrCreate(dir)
	if len(cfg.HostnameRemovals["gone"]) != 0 {
		t.Fatal("retired primary cleanup pending")
	}
}

func TestNilCommandHostnameSyncForCustomContainer(t *testing.T) {
	t.Setenv("XDG_CONFIG_HOME", t.TempDir())
	cfg := config.Default()
	cfg.LocalProxy.Enabled = true
	cfg.Images["custom"] = config.ImageConfig{Kind: "custom"}
