		t.Fatal(err)
	}
	if err := syncContainerHostnames(nil, cfg, "forum"); err != nil {
		t.Fatal(err)
	}
	syncContainerHostnamesBestEffort(nil, cfg, "forum")
}

func TestProxyExtraHostsIncludesAliases(t *testing.T) {
	cfg := config.Default()
	cfg.HostnameAliases = map[string][]string{"forum": {"customers.dev.home.arpa"}}
	got := proxyExtraHosts(cfg, "forum", "forum.dev.home.arpa")
	if strings.Join(got, ",") != "forum.dev.home.arpa:127.0.0.1,customers.dev.home.arpa:127.0.0.1" {
		t.Fatal(got)
	}
	if got := proxyExtraHosts(cfg, "forum", ""); len(got) != 0 {
		t.Fatal(got)
	}
}

func TestHostnameOperationLockHonorsCancellation(t *testing.T) {
	t.Setenv("XDG_CONFIG_HOME", t.TempDir())
	entered, release, done := make(chan struct{}), make(chan struct{}), make(chan error, 1)
	go func() { done <- withHostnameOperationLock(nil, func() error { close(entered); <-release; return nil }) }()
	<-entered
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)
	defer cancel()
	cmd := &cobra.Command{}
	cmd.SetContext(ctx)
	err := withHostnameOperationLock(cmd, func() error { return fmt.Errorf("unexpected lock acquisition") })
	close(release)
	if first := <-done; first != nil {
		t.Fatal(first)
	}
	if !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("lock error: %v", err)
	}
}

func TestLifecycleReloadsNewAliasAfterStartupSnapshot(t *testing.T) {
	cmd, dir, log, _ := setupHostnameReconcileTest(t)
	stale, _ := config.LoadOrCreate(dir)
	if err := config.Update(dir, func(cfg *config.Config) error {
		cfg.HostnameAliases = map[string][]string{"forum": {"customers.dev.home.arpa"}}
		return nil
	}); err != nil {
		t.Fatal(err)
	}
	syncContainerHostnamesBestEffort(cmd, stale, "forum")
	data, err := os.ReadFile(log)
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(data), "customers.dev.home.arpa") {
		t.Fatal("new aliases skipped by stale startup snapshot")
	}
}

func TestServeRenameUsesHostnameLifecycle(t *testing.T) {
	_, dir, log, _ := setupHostnameReconcileTest(t)
	if err := config.Update(dir, func(cfg *config.Config) error {
		cfg.HostnameAliases = map[string][]string{"forum": {"customers.dev.home.arpa"}}
		return nil
	}); err != nil {
		t.Fatal(err)
	}
	oldExists, oldRename := renameDockerExists, renameDockerRenameContext
	renameDockerExists = func(name string) bool { return name == "forum" }
	renameDockerRenameContext = func(context.Context, string, string, io.Writer, io.Writer) error { return nil }
	t.Cleanup(func() { renameDockerExists, renameDockerRenameContext = oldExists, oldRename })
	out := httptest.NewRecorder()
	handleContainerRename(out, httptest.NewRequest("POST", "/", strings.NewReader(`{"new_name":"shop"}`)), dir, "forum")
	if out.Code != 200 {
		t.Fatalf("rename response %d: %s", out.Code, out.Body.String())
	}
	cfg, _ := config.LoadOrCreate(dir)
	if len(cfg.HostnameAliases["shop"]) != 1 || len(cfg.HostnameAliases["forum"]) != 0 {
		t.Fatal("web rename lost aliases")
	}
	data, err := os.ReadFile(log)
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(data), "shop.dev.home.arpa,customers.dev.home.arpa") {
		t.Fatal("web rename skipped runtime sync")
	}
}

func TestServeDeleteUsesHostnameLifecycle(t *testing.T) {
	_, dir, _, _ := setupHostnameReconcileTest(t)
	if err := config.Update(dir, func(cfg *config.Config) error {
		cfg.HostnameAliases = map[string][]string{"forum": {"customers.dev.home.arpa"}}
		return nil
	}); err != nil {
		t.Fatal(err)
	}
	restore := stubRemoveDocker(t)
	defer restore()
	out := httptest.NewRecorder()
	handleContainerDelete(out, httptest.NewRequest("POST", "/", strings.NewReader(`{"force":true}`)), dir, "forum")
	if out.Code != 200 {
		t.Fatalf("delete response %d: %s", out.Code, out.Body.String())
	}
	cfg, _ := config.LoadOrCreate(dir)
	if _, ok := cfg.HostnameAliases["forum"]; ok {
		t.Fatal("web delete left alias owner")
	}
	if len(cfg.HostnameRemovals["forum"]) != 0 {
		t.Fatal("web delete did not clean live routes")
	}
}

package assets

import (
	"crypto/sha256"
	_ "embed"
	"encoding/hex"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
)

// We embed a copy of the repository's Dockerfile (kept in this package
// directory) so the binary can materialize it into the XDG config directory
// if needed.
//
//go:embed Dockerfile
var embeddedDockerfile []byte

//go:embed Dockerfile.update.discourse
var embeddedDockerfileUpdateDiscourse []byte

// EmbeddedDockerfileSHA256 returns the hex-encoded SHA-256 of the embedded Dockerfile.
func EmbeddedDockerfileSHA256() string {
	sum := sha256.Sum256(embeddedDockerfile)
	return hex.EncodeToString(sum[:])
}

// ResolveDockerfile determines which Dockerfile to use and ensures it exists.
// Priority:
// 1) Environment variable DV_DOCKERFILE points to an existing file
// 2) A user-provided override at <configDir>/Dockerfile.local
// 3) The embedded Dockerfile, extracted to <configDir>/Dockerfile if missing or outdated
// It returns (dockerfilePath, contextDir, usedOverride, error)
func ResolveDockerfile(configDir string) (string, string, bool, error) {
	return resolveDockerfileInternal(configDir, "Dockerfile", embeddedDockerfile, EmbeddedDockerfileSHA256())
}

// EmbeddedDockerfileUpdateDiscourseSHA256 returns the hex-encoded SHA-256 of the embedded update Dockerfile.
func EmbeddedDockerfileUpdateDiscourseSHA256() string {
	sum := sha256.Sum256(embeddedDockerfileUpdateDiscourse)
	return hex.EncodeToString(sum[:])
}

// ResolveDockerfileUpdateDiscourse resolves the update Dockerfile used by `dv update discourse`.
// Priority:
// 1) DV_DOCKERFILE_UPDATE_DISCOURSE env var
// 2) <configDir>/Dockerfile.update.discourse.local
// 3) embedded Dockerfile.update.discourse at <configDir>/Dockerfile.update.discourse
func ResolveDockerfileUpdateDiscourse(configDir string) (string, string, bool, error) {
	return resolveDockerfileInternal(configDir, "Dockerfile.update.discourse", embeddedDockerfileUpdateDiscourse, EmbeddedDockerfileUpdateDiscourseSHA256())
}

// resolveDockerfileInternal is a helper function to resolve Dockerfiles with different names
func resolveDockerfileInternal(configDir string, fileName string, embeddedContent []byte, embeddedSHA string) (string, string, bool, error) {
	// Env override takes precedence
	envVar := "DV_DOCKERFILE"
	if fileName == "Dockerfile.update.discourse" {
		envVar = "DV_DOCKERFILE_UPDATE_DISCOURSE"
	}
	if envPath, ok := os.LookupEnv(envVar); ok && envPath != "" {
		if info, err := os.Stat(envPath); err == nil && !info.IsDir() {
			return envPath, filepath.Dir(envPath), true, nil
		}
		return "", "", false, fmt.Errorf("%s path does not exist: %s", envVar, envPath)
	}

	// Local override in config directory
	localSuffix := ".local"
	localOverride := filepath.Join(configDir, fileName+localSuffix)
	if info, err := os.Stat(localOverride); err == nil && !info.IsDir() {
		return localOverride, configDir, true, nil
	}

	// Fallback to embedded Dockerfile with SHA-based update
	if err := os.MkdirAll(configDir, 0o755); err != nil {
		return "", "", false, err
	}
	targetPath := filepath.Join(configDir, fileName)
	shaPath := filepath.Join(configDir, fileName+".sha256")

	// Use the provided SHA from the calling function
	needWrite := false

	// Decide whether to write/update the Dockerfile
	if b, err := os.ReadFile(shaPath); err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			needWrite = true
		} else {
			return "", "", false, err
		}
	} else if string(trimSpaceBytes(b)) != embeddedSHA {
		needWrite = true
	}

	if needWrite {
		if err := os.WriteFile(targetPath, embeddedContent, 0o644); err != nil {
			return "", "", false, err
		}
		if err := os.WriteFile(shaPath, []byte(embeddedSHA+"\n"), 0o644); err != nil {
			return "", "", false, err
		}
	}

	return targetPath, configDir, false, nil
}

func trimSpaceBytes(b []byte) []byte {
	// minimal trim to avoid allocating strings while comparing
	start, end := 0, len(b)
	for start < end {
		c := b[start]
		if c == ' ' || c == '\n' || c == '\r' || c == '\t' {
			start++
			continue
		}
		break
	}
	for end > start {
		c := b[end-1]
		if c == ' ' || c == '\n' || c == '\r' || c == '\t' {
			end--
			continue
		}
		break
	}
	return b[start:end]
}

package cli

import (
	"os"
	"path/filepath"
	"strings"
)

const shellActionDirEnv = "DV_SHELL_ACTION_DIR"

const (
	shellActionChdir      = "chdir"
	shellActionAgent      = "agent"
	shellActionAgentUnset = "agent-unset"
)

// writeShellAction sends a data-only action to an installed shell wrapper.
// Commands behave normally when shell integration is not active.
func writeShellAction(name, value string) {
	dir := os.Getenv(shellActionDirEnv)
	if dir == "" {
		return
	}
	info, err := os.Stat(dir)
	if err != nil || !info.IsDir() {
		return
	}
	_ = os.WriteFile(filepath.Join(dir, name), []byte(value+"\n"), 0o600)
}

func environmentWithout(env []string, keys ...string) []string {
	blocked := make(map[string]struct{}, len(keys))
	for _, key := range keys {
		blocked[key] = struct{}{}
	}
	filtered := make([]string, 0, len(env))
	for _, entry := range env {
		key, _, ok := strings.Cut(entry, "=")
		if ok {
			if _, remove := blocked[key]; remove {
				continue
			}
		}
		filtered = append(filtered, entry)
	}
	return filtered
}

func requestShellChdir(dir string) {
	writeShellAction(shellActionChdir, dir)
}

func requestShellAgent(agent string) {
	dir := os.Getenv(shellActionDirEnv)
	if dir == "" {
		return
	}
	if agent == "" {
		writeShellAction(shellActionAgentUnset, "")
		_ = os.Remove(filepath.Join(dir, shellActionAgent))
		return
	}
	writeShellAction(shellActionAgent, agent)
	_ = os.Remove(filepath.Join(dir, shellActionAgentUnset))
}

