package cli

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/spf13/cobra"

	"dv/internal/config"
	"dv/internal/discourse"
	"dv/internal/docker"
	"dv/internal/xdg"
)

var configMcpCmd = &cobra.Command{
	Use:   "mcp NAME",
	Short: "Configure an MCP server in the running container",
	Args:  cobra.ExactArgs(1),
	ValidArgs: []string{
		"playwright",
		"discourse",
		"chrome-devtools",
	},
	RunE: func(cmd *cobra.Command, args []string) error {
		configDir, err := xdg.ConfigDir()
		if err != nil {
			return err
		}
		cfg, err := config.LoadOrCreate(configDir)
		if err != nil {
			return err
		}

		containerName, _ := cmd.Flags().GetString("name")
		if containerName == "" {
			containerName = currentAgentName(cfg)
		}

		if !docker.Exists(containerName) {
			fmt.Fprintf(cmd.OutOrStdout(), "Container '%s' does not exist. Run 'dv start' first.\n", containerName)
			return nil
		}
		if !docker.Running(containerName) {
			fmt.Fprintf(cmd.OutOrStdout(), "Starting container '%s'...\n", containerName)
			if err := startContainerWithPostStartHook(cmd, cfg, configDir, containerName, "config mcp"); err != nil {
				return err
			}
		}

		// Determine workdir from the associated image if known; fall back to selected image
		imgName := cfg.ContainerImages[containerName]
		var imgCfg config.ImageConfig
		if imgName != "" {
			imgCfg = cfg.Images[imgName]
		} else {
			_, imgCfg, err = resolveImage(cfg, "")
			if err != nil {
				return err
			}
		}
		workdir := imgCfg.Workdir

		mcpName := strings.ToLower(strings.TrimSpace(args[0]))

		// Prepare env pass-through so tools like 'claude' have credentials
		envs := collectEnvPassthrough(cfg)
		if !hasClaudeHostCredentials() {
			fmt.Fprintln(cmd.ErrOrStderr(), "Warning: neither ANTHROPIC_API_KEY nor CLAUDE_CODE_OAUTH_TOKEN is set on host; 'claude' may fail.")
		}

		switch mcpName {
		case "playwright":
			return configurePlaywrightMCP(cmd, containerName, workdir, envs)
		case "discourse":
			return configureDiscourseMCP(cmd, containerName, workdir, envs)
		case "chrome-devtools":
			return configureChromeDevToolsMCP(cmd, containerName, workdir, envs)
		default:
			return fmt.Errorf("unsupported MCP name: %s (supported: playwright, discourse, chrome-devtools)", mcpName)
		}
	},
}

func init() {
	configMcpCmd.Flags().String("name", "", "Container name (defaults to selected or default)")
	configCmd.AddCommand(configMcpCmd)
}

func hasClaudeHostCredentials() bool {
	if strings.TrimSpace(os.Getenv("ANTHROPIC_API_KEY")) != "" {
		return true
	}
	if strings.TrimSpace(os.Getenv("CLAUDE_CODE_OAUTH_TOKEN")) != "" {
		return true
	}
	return false
}

// addOrReplaceTomlSection inserts or replaces a TOML table section defined by sectionHeader
// (e.g., "mcp_servers.playwright"). The sectionBody should include the full header line and
// any key/value lines below it, and may end with a trailing newline.
func addOrReplaceTomlSection(existing string, sectionHeader string, sectionBody string) string {
	// Normalize endings
	existing = strings.ReplaceAll(existing, "\r\n", "\n")
	lines := []string{}
	if strings.TrimSpace(existing) != "" {
		lines = strings.Split(existing, "\n")
	}
	headerLine := "[" + sectionHeader + "]"

	// Find existing section
	start := -1
	for i, ln := range lines {
		if strings.TrimSpace(ln) == headerLine {
			start = i
			break
		}
	}

	if start == -1 {
		// Append section to the end
		var b strings.Builder
		if strings.TrimSpace(existing) != "" {
			b.WriteString(strings.TrimRight(existing, "\n"))
			b.WriteString("\n\n")
		}
		b.WriteString(strings.TrimRight(sectionBody, "\n"))
		b.WriteString("\n")
		return b.String()
	}

	// Determine end of existing section (next header or EOF)
	end := len(lines)
	for j := start + 1; j < len(lines); j++ {
		if strings.HasPrefix(strings.TrimSpace(lines[j]), "[") {
			end = j
			break
		}
	}
	// Rebuild with replacement
	var out []string
	out = append(out, lines[:start]...)
	// Add new body (without trailing newline to manage joins consistently)
	for _, l := range strings.Split(strings.TrimRight(sectionBody, "\n"), "\n") {
		out = append(out, l)
	}
	if end < len(lines) {
		// Ensure a blank line between sections if not already present
		if len(out) > 0 && strings.TrimSpace(out[len(out)-1]) != "" {
			out = append(out, "")
		}
		out = append(out, lines[end:]...)
	}
	// Ensure trailing newline
	return strings.TrimRight(strings.Join(out, "\n"), "\n") + "\n"
}

func configurePlaywrightMCP(cmd *cobra.Command, containerName, workdir string, envs docker.Envs) error {
	mcpConfig := mcpConfiguration{
		name:            "playwright",
		registrationCmd: "claude mcp add -s user playwright -- npx -y @playwright/mcp@latest --isolated --no-sandbox --headless --executable-path /usr/bin/chromium",
		codexCommand:    "npx",
		codexArgs:       []string{"-y", "@playwright/mcp@latest", "--isolated", "--no-sandbox", "--headless", "--executable-path", "/usr/bin/chromium"},
		geminiCommand:   "npx",
		geminiArgs:      []string{"-y", "@playwright/mcp@latest", "--isolated", "--no-sandbox", "--headless", "--executable-path", "/usr/bin/chromium"},
	}
	return configureMCP(cmd, containerName, workdir, envs, mcpConfig)
}

func configureChromeDevToolsMCP(cmd *cobra.Command, containerName, workdir string, envs docker.Envs) error {
	mcpConfig := mcpConfiguration{
		name:            "chrome-devtools",
		registrationCmd: "claude mcp add -s user chrome-devtools -- npx -y chrome-devtools-mcp@latest --headless",
		codexCommand:    "npx",
		codexArgs:       []string{"-y", "chrome-devtools-mcp@latest", "--headless"},
		geminiCommand:   "npx",
		geminiArgs:      []string{"-y", "chrome-devtools-mcp@latest", "--headless"},
	}
	return configureMCP(cmd, containerName, workdir, envs, mcpConfig)
}

func configureDiscourseMCP(cmd *cobra.Command, containerName, workdir string, envs docker.Envs) error {
	// Dynamically determine the home directory for the discourse user
	homeDirRaw, err := docker.ExecOutput(containerName, "/", nil, []string{"bash", "-lc", "echo $HOME"})
	if err != nil {
		return fmt.Errorf("failed to determine home directory in container: %w", err)
	}
	homeDir := strings.TrimSpace(homeDirRaw)
	if homeDir == "" {
		homeDir = "/home/discourse" // fallback
	}

	profilePath := filepath.Join(homeDir, ".config/discourse-mcp/local.json")
	profileDir := filepath.Join(homeDir, ".config/discourse-mcp")
	const siteURL = "http://127.0.0.1:3000"
	const apiKeyDescription = "dv discourse-mcp"

	fmt.Fprintln(cmd.OutOrStdout(), "Preparing Discourse MCP profile with read/write access to local instance...")

	if _, err := docker.ExecOutput(containerName, workdir, nil, []string{"bash", "-lc", "mkdir -p " + profileDir}); err != nil {
		return fmt.Errorf("failed to ensure discourse-mcp config directory: %w", err)
	}

	readCmd := fmt.Sprintf("if [ -f %q ]; then cat %q; fi", profilePath, profilePath)
	existingProfile, err := docker.ExecOutput(containerName, workdir, nil, []string{"bash", "-lc", readCmd})
	if err != nil {
		return fmt.Errorf("failed to read existing MCP profile: %w", err)
	}

	profile := map[string]any{}
	if strings.TrimSpace(existingProfile) != "" {
		if err := json.Unmarshal([]byte(existingProfile), &profile); err != nil {
			fmt.Fprintf(cmd.ErrOrStderr(), "Warning: existing MCP profile is invalid JSON, regenerating it: %v\n", err)
			profile = map[string]any{}
		}
	}

	authPairs := extractAuthPairs(profile)
	var pair map[string]any
	for _, candidate := range authPairs {
		if site, ok := candidate["site"].(string); ok && strings.EqualFold(site, siteURL) {
			pair = candidate
			break
		}
	}
	if pair == nil {
		pair = map[string]any{}
		authPairs = append(authPairs, pair)
	}

	apiKey := ""
	adminUsername := ""
	if existing, ok := pair["api_key"].(string); ok {
		apiKey = [REDACTED]
	}
	if existingUsername, ok := pair["api_username"].(string); ok {
		adminUsername = strings.TrimSpace(existingUsername)
	}
	if apiKey == "" || adminUsername == "" {
		fmt.Fprintln(cmd.OutOrStdout(), "Generating Discourse API key for admin user inside container...")
		generated, err := discourse.GenerateAPIKey(discourse.GenerateAPIKeyOptions{
			ContainerName: containerName,
			Workdir:       workdir,
			Description:   apiKeyDescription,
			Envs:          envs,
			Verbose:       false,
		})
		if err != nil {
			return fmt.Errorf("failed to create Discourse API key: %w", err)
		}
		apiKey = [REDACTED]
		adminUsername = generated.Username
	} else {
		fmt.Fprintln(cmd.OutOrStdout(), "Reusing existing Discourse API key for admin user from MCP profile.")
	}

	pair["site"] = siteURL
	pair["api_key"] = apiKey
	pair["api_username"] = adminUsername
	profile["auth_pairs"] = authPairs
	profile["read_only"] = false
	profile["allow_writes"] = true
	profile["site"] = siteURL
	if _, ok := profile["log_level"]; !ok {
		profile["log_level"] = "info"
	}

	profileBytes, err := json.MarshalIndent(profile, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal MCP profile: %w", err)
	}

	tmpDir, err := os.MkdirTemp("", "discourse-mcp-profile-*")
	if err != nil {
		return err
	}
	defer os.RemoveAll(tmpDir)
	tmpProfile := filepath.Join(tmpDir, "local.json")
	if err := os.WriteFile(tmpProfile, profileBytes, 0o600); err != nil {
		return fmt.Errorf("failed to write temporary MCP profile: %w", err)
	}

	if err := docker.CopyToContainerWithOwnership(containerName, tmpProfile, profilePath, false); err != nil {
		return fmt.Errorf("failed to copy MCP profile into container: %w", err)
	}

	mcpConfig := mcpConfiguration{
		name:            "discourse",
		registrationCmd: fmt.Sprintf("claude mcp add -s user discourse -- npx -y @discourse/mcp@latest --profile %s", profilePath),
		codexCommand:    "npx",
		codexArgs:       []string{"-y", "@discourse/mcp@latest", "--profile", profilePath},
		geminiCommand:   "npx",
		geminiArgs:      []string{"-y", "@discourse/mcp@latest", "--profile", profilePath},
	}

	return configureMCP(cmd, containerName, workdir, envs, mcpConfig)
}

// mcpConfiguration holds the configuration for setting up an MCP server
type mcpConfiguration struct {
	name            string            // MCP server name (e.g., "playwright", "discourse")
	registrationCmd string            // Command to register with Claude
	codexCommand    string            // Command for Codex config
	codexArgs       []string          // Arguments for Codex config
	geminiCommand   string            // Command for Gemini config
	geminiArgs      []string          // Arguments for Gemini config
	env             map[string]string // Environment variables for the MCP server
}

// configureMCP registers an MCP server with Claude, Codex, and Gemini
func configureMCP(cmd *cobra.Command, containerName, workdir string, envs docker.Envs, mcpConfig mcpConfiguration) error {
	// Dynamically determine the home directory for the discourse user
	homeDirRaw, err := docker.ExecOutput(containerName, "/", nil, []string{"bash", "-lc", "echo $HOME"})
	if err != nil {
		return fmt.Errorf("failed to determine home directory in container: %w", err)
	}
	homeDir := strings.TrimSpace(homeDirRaw)
	if homeDir == "" {
		homeDir = "/home/discourse" // fallback
	}

	codexConfigPath := filepath.Join(homeDir, ".codex/config.toml")
	geminiConfigPath := filepath.Join(homeDir, ".gemini/settings.json")

	// Remove existing Claude MCP entry
	removeEchoCmd := fmt.Sprintf("claude mcp remove -s user %s", mcpConfig.name)
	removeCmd := removeEchoCmd + " || true"

	fmt.Fprintf(cmd.OutOrStdout(), "Ensuring no existing Claude MCP '%s' remains (safe to ignore failures)...\n", mcpConfig.name)
	fmt.Fprintf(cmd.OutOrStdout(), "Running: %s\n\n", removeEchoCmd)
	if err := docker.ExecInteractive(containerName, workdir, envs, []string{"bash", "-lc", removeCmd}); err != nil {
		// Ignore errors from removal; proceed to add
	}

	// Register MCP with Claude
	fmt.Fprintf(cmd.OutOrStdout(), "Registering MCP '%s' with Claude inside container '%s'...\n", mcpConfig.name, containerName)
	fmt.Fprintf(cmd.OutOrStdout(), "Running: %s\n\n", mcpConfig.registrationCmd)

	if err := docker.ExecInteractive(containerName, workdir, envs, []string{"bash", "-lc", mcpConfig.registrationCmd}); err != nil {
		return err
	}

	tmpDir, err := os.MkdirTemp("", "mcp-config-*")
	if err != nil {
		return err
	}
	defer os.RemoveAll(tmpDir)

	// Configure Codex
	fmt.Fprintf(cmd.OutOrStdout(), "\nConfiguring Codex to use the %s MCP (updating ~/.codex/config.toml)...\n", mcpConfig.name)

	_, _ = docker.ExecOutput(containerName, workdir, nil, []string{"bash", "-lc", "mkdir -p ~/.codex"})
	existsOut, _ := docker.ExecOutput(containerName, workdir, nil, []string{"bash", "-lc", "test -f " + codexConfigPath + " && echo EXISTS || echo MISSING"})
	hasCodexConfig := strings.Contains(existsOut, "EXISTS")

	hostCodexCfg := filepath.Join(tmpDir, "codex-config.toml")
	var codexContent string
	if hasCodexConfig {
		if err := docker.CopyFromContainer(containerName, codexConfigPath, hostCodexCfg); err != nil {
			return fmt.Errorf("failed to copy existing Codex config: %w", err)
		}
		b, err := os.ReadFile(hostCodexCfg)
		if err != nil {
			return err
		}
		codexContent = string(b)
	}

	codexSectionHeader := fmt.Sprintf("mcp_servers.%s", mcpConfig.name)
	argsJSON, err := json.Marshal(mcpConfig.codexArgs)
	if err != nil {
		return fmt.Errorf("failed to marshal codex args: %w", err)
	}
	codexSectionBody := strings.Join([]string{
		"[" + codexSectionHeader + "]",
		fmt.Sprintf("command = %q", mcpConfig.codexCommand),
		fmt.Sprintf("args = %s", string(argsJSON)),
		"",
	}, "\n")

	codexUpdated := addOrReplaceTomlSection(codexContent, codexSectionHeader, codexSectionBody)
	if err := os.WriteFile(hostCodexCfg, []byte(codexUpdated), 0o644); err != nil {
		return err
	}

	if err := docker.CopyToContainerWithOwnership(containerName, hostCodexCfg, codexConfigPath, false); err != nil {
		return fmt.Errorf("failed to copy Codex config into container: %w", err)
	}

	// Configure Gemini
	fmt.Fprintf(cmd.OutOrStdout(), "\nConfiguring Gemini CLI to use the %s MCP (updating ~/.gemini/settings.json)...\n", mcpConfig.name)

	_, _ = docker.ExecOutput(containerName, workdir, nil, []string{"bash", "-lc", "mkdir -p ~/.gemini"})
	existsOut, _ = docker.ExecOutput(containerName, workdir, nil, []string{"bash", "-lc", "test -f " + geminiConfigPath + " && echo EXISTS || echo MISSING"})
	hasGeminiConfig := strings.Contains(existsOut, "EXISTS")

	hostGeminiCfg := filepath.Join(tmpDir, "gemini-settings.json")
	geminiSettings := map[string]any{}

	if hasGeminiConfig {
		if err := docker.CopyFromContainer(containerName, geminiConfigPath, hostGeminiCfg); err != nil {
			return fmt.Errorf("failed to copy existing Gemini settings: %w", err)
		}
		b, err := os.ReadFile(hostGeminiCfg)
		if err != nil {
			return err
		}
		if len(b) > 0 {
			if err := json.Unmarshal(b, &geminiSettings); err != nil {
				fmt.Fprintf(cmd.ErrOrStderr(), "Warning: existing Gemini settings are invalid JSON, regenerating: %v\n", err)
				geminiSettings = map[string]any{}
			}
		}
	}

	mcpServersRaw, ok := geminiSettings["mcpServers"]
	var mcpServers map[string]any
	if ok {
		mcpServers, _ = mcpServersRaw.(map[string]any)
	}
	if mcpServers == nil {
		mcpServers = map[string]any{}
	}

	serverCfg := map[string]any{
		"command": mcpConfig.geminiCommand,
		"args":    mcpConfig.geminiArgs,
	}
	if len(mcpConfig.env) > 0 {
		serverCfg["env"] = mcpConfig.env
	}
	mcpServers[mcpConfig.name] = serverCfg
	geminiSettings["mcpServers"] = mcpServers

	geminiUpdated, err := json.MarshalIndent(geminiSettings, "", "  ")
	if err != nil {
		return err
	}
	if err := os.WriteFile(hostGeminiCfg, geminiUpdated, 0o644); err != nil {
		return err
	}

	if err := docker.CopyToContainerWithOwnership(containerName, hostGeminiCfg, geminiConfigPath, false); err != nil {
		return fmt.Errorf("failed to copy Gemini settings into container: %w", err)
	}

	fmt.Fprintf(cmd.OutOrStdout(), "%s MCP configuration complete.\n", strings.Title(mcpConfig.name))
	return nil
}

func extractAuthPairs(profile map[string]any) []map[string]any {
	raw, ok := profile["auth_pairs"]
	if !ok {
		return []map[string]any{}
	}
	arr, ok := raw.([]any)
	if !ok {
		return []map[string]any{}
	}
	pairs := make([]map[string]any, 0, len(arr))
	for _, item := range arr {
		if m, ok := item.(map[string]any); ok {
			pairs = append(pairs, m)
		}
	}
	return pairs
}

// Package discourse provides a centralized HTTP client for the Discourse Admin API
// with automatic API key generation, caching, and recovery.
package discourse

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os/exec"
	"regexp"
	"strconv"
	"strings"
	"time"

	"dv/internal/config"
	"dv/internal/docker"
)

const (
	// APIKeyDescription is the description used when creating API keys
	APIKeyDescription = "dv-api-client"
	// ContainerKeyPath is where the API key is stored inside the container
	ContainerKeyPath = "/home/discourse/.dv/api_key"
	// DefaultTimeout for HTTP requests
	DefaultTimeout = 30 * time.Second
)

// Client provides HTTP-based access to Discourse Admin APIs
type Client struct {
	BaseURL       string
	APIKey        string
	APIUsername   string
	ContainerName string
	Workdir       string
	Verbose       bool
	Envs          docker.Envs // Environment variables for container execution
	httpClient    *http.Client

	// hostKeyCache is the path to the host-side key cache file
	hostKeyCache string
}

// KeyCache represents the host-side API key cache
type KeyCache struct {
	Keys map[string]KeyEntry `json:"keys"`
}

// KeyEntry is a single cached API key
type KeyEntry struct {
	APIKey    string    `json:"api_key"`
	Username  string    `json:"username"`
	CreatedAt time.Time `json:"created_at"`
}

// NewClient creates a new Discourse API client for the given container.
// It automatically discovers the base URL and loads cached credentials.
func NewClient(containerName string, cfg config.Config, envs docker.Envs, verbose bool) (*Client, error) {
	imgCfg := cfg.Images[cfg.SelectedImage]
	workdir := config.EffectiveWorkdir(cfg, imgCfg, containerName)

	baseURL, err := DiscoverBaseURL(containerName, cfg)
	if err != nil {
		return nil, fmt.Errorf("discover base URL: %w", err)
	}

	c := &Client{
		BaseURL:       baseURL,
		ContainerName: containerName,
		Workdir:       workdir,
		Verbose:       verbose,
		Envs:          envs,
		httpClient: &http.Client{
			Timeout: DefaultTimeout,
		},
	}

	return c, nil
}

// NewClientWithURL creates a client with an explicit base URL (for testing or custom setups)
func NewClientWithURL(containerName, baseURL, workdir string, envs docker.Envs, verbose bool) *Client {
	return &Client{
		BaseURL:       baseURL,
		ContainerName: containerName,
		Workdir:       workdir,
		Verbose:       verbose,
		Envs:          envs,
		httpClient: &http.Client{
			Timeout: DefaultTimeout,
		},
	}
}

// EnsureAPIKey ensures we have a valid API key, generating one if needed.
// This is the main entry point for key management.
func (c *Client) EnsureAPIKey() error {
	// Step 1: Try loading from container file
	if err := c.loadKeyFromContainer(); err == nil {
		// Step 2: Verify the key works
		if err := c.testConnection(); err == nil {
			return nil
		}
		c.verboseLog("Cached key invalid, regenerating...")
	}

	// Step 3: Generate new key via Rails
	if err := c.generateKey(); err != nil {
		return fmt.Errorf("generate API key: %w", err)
	}

	// Step 4: Verify the new key works
	if err := c.testConnection(); err != nil {
		return fmt.Errorf("verify new key: %w", err)
	}

	return nil
}

// GetAPIKey returns the current API key and username, ensuring one exists.
func (c *Client) GetAPIKey() (apiKey, username string, err error) {
	if c.APIKey == "" {
		if err := c.EnsureAPIKey(); err != nil {
			return "", "", err
		}
	}
	return c.APIKey, c.APIUsername, nil
}

// loadKeyFromContainer reads the cached API key from the container filesystem
func (c *Client) loadKeyFromContainer() error {
	if !docker.Running(c.ContainerName) {
		return fmt.Errorf("container not running")
	}

	readCmd := fmt.Sprintf("cat %s 2>/dev/null", shellQuote(ContainerKeyPath))
	out, err := docker.ExecOutput(c.ContainerName, c.Workdir, c.Envs, []string{"bash", "-c", readCmd})
	if err != nil {
		return fmt.Errorf("read key file: %w", err)
	}

	lines := strings.Split(strings.TrimSpace(out), "\n")
	if len(lines) < 2 {
		return fmt.Errorf("invalid key file format")
	}

	c.APIKey = [REDACTED]])
	c.APIUsername = strings.TrimSpace(lines[1])

	if c.APIKey == "" || c.APIUsername == "" {
		return fmt.Errorf("empty key or username")
	}

	c.verboseLog("Loaded API key from container cache")
	return nil
}

// generateKey creates a new API key via Rails runner and saves it to the container
func (c *Client) generateKey() error {
	if !docker.Running(c.ContainerName) {
		return fmt.Errorf("container %s not running - run 'dv start' first", c.ContainerName)
	}

	generated, err := GenerateAPIKey(GenerateAPIKeyOptions{
		ContainerName: c.ContainerName,
		Workdir:       c.Workdir,
		Description:   APIKeyDescription,
		Envs:          c.Envs,
		Verbose:       c.Verbose,
	})
	if err != nil {
		return err
	}

	c.APIKey = [REDACTED]
	c.APIUsername = generated.Username

	// Save to container file
	if err := c.saveKeyToContainer(); err != nil {
		c.verboseLog("Warning: failed to cache key: %v", err)
		// Non-fatal, we can still use the key
	}

	c.verboseLog("Generated new API key for user %s", c.APIUsername)
	return nil
}

// saveKeyToContainer writes the API key to the container filesystem for caching
func (c *Client) saveKeyToContainer() error {
	content := fmt.Sprintf("%s\n%s\n", c.APIKey, c.APIUsername)
	saveCmd := fmt.Sprintf(
		"install -d -m 700 %s && printf '%%s' %s > %s && chmod 600 %s",
		shellQuote("/home/discourse/.dv"),
		shellQuote(content),
		shellQuote(ContainerKeyPath),
		shellQuote(ContainerKeyPath),
	)
	_, err := docker.ExecOutput(c.ContainerName, c.Workdir, c.Envs, []string{"bash", "-c", saveCmd})
	return err
}

// testConnection verifies the API key works by making a simple request.
// Keep this independent of plugin-provided settings; during early boot or after
// plugin changes, probing an AI-specific site setting can fail with a Rails 500
// even when the generated API key is valid.
func (c *Client) testConnection() error {
	if c.APIKey == "" {
		return fmt.Errorf("no API key set")
	}

	req, err := http.NewRequest("GET", c.BaseURL+"/session/current.json", nil)
	if err != nil {
		return err
	}
	c.setAuthHeaders(req)

	resp, err := c.httpClient.Do(req)
	if err != nil {
		return fmt.Errorf("connection failed: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode == 401 || resp.StatusCode == 403 {
		return fmt.Errorf("authentication failed (status %d)", resp.StatusCode)
	}
	if resp.StatusCode >= 500 {
		body, _ := io.ReadAll(io.LimitReader(resp.Body, 4096))
		c.verboseLog("API key verification got server status %d; assuming key is usable and continuing: %s", resp.StatusCode, strings.TrimSpace(string(body)))
		return nil
	}
	if resp.StatusCode != 200 {
		body, _ := io.ReadAll(io.LimitReader(resp.Body, 4096))
		return fmt.Errorf("unexpected status: %d: %s", resp.StatusCode, strings.TrimSpace(string(body)))
	}

	return nil
}

// setAuthHeaders adds the required API authentication headers
func (c *Client) setAuthHeaders(req *http.Request) {
	req.Header.Set("Api-Key", c.APIKey)
	req.Header.Set("Api-Username", c.APIUsername)
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("Accept", "application/json")
}

// doRequest performs an HTTP request with automatic key recovery on auth failure
func (c *Client) doRequest(method, path string, body interface{}) (*http.Response, []byte, error) {
	// Ensure we have a key
	if c.APIKey == "" {
		if err := c.EnsureAPIKey(); err != nil {
			return nil, nil, err
		}
	}

	resp, respBody, err := c.doRequestOnce(method, path, body)
	if err != nil {
		return nil, nil, err
	}

	// Auto-recovery on auth failure
	if resp.StatusCode == 401 || resp.StatusCode == 403 {
		c.verboseLog("Auth failed, regenerating key...")
		if err := c.generateKey(); err != nil {
			return nil, nil, fmt.Errorf("key regeneration failed: %w", err)
		}
		// Retry once with new key
		return c.doRequestOnce(method, path, body)
	}

	return resp, respBody, nil
}

// doRequestOnce performs a single HTTP request without retry
func (c *Client) doRequestOnce(method, path string, body interface{}) (*http.Response, []byte, error) {
	var bodyReader io.Reader
	if body != nil {
		jsonBody, err := json.Marshal(body)
		if err != nil {
			return nil, nil, fmt.Errorf("marshal body: %w", err)
		}
		bodyReader = bytes.NewReader(jsonBody)
	}

	url := c.BaseURL + path
	req, err := http.NewRequest(method, url, bodyReader)
	if err != nil {
		return nil, nil, err
	}
	c.setAuthHeaders(req)

	c.verboseLog("%s %s", method, url)

	resp, err := c.httpClient.Do(req)
	if err != nil {
		return nil, nil, err
	}
	defer resp.Body.Close()

	respBody, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, nil, fmt.Errorf("read response: %w", err)
	}

	return resp, respBody, nil
}

// verboseLog prints debug output when verbose mode is enabled
func (c *Client) verboseLog(format string, args ...interface{}) {
	if c.Verbose {
		fmt.Printf("[discourse-api] "+format+"\n", args...)
	}
}

func shellQuote(s string) string {
	return "'" + strings.ReplaceAll(s, "'", "'\"'\"'") + "'"
}

// DiscoverBaseURL determines the correct URL to reach a container's Discourse instance
func DiscoverBaseURL(containerName string, cfg config.Config) (string, error) {
	// Option 1: Local proxy is enabled - use NAME.hostname
	if cfg.LocalProxy.Enabled {
		host := hostnameForContainer(containerName, cfg.LocalProxy.Hostname)
		port := cfg.LocalProxy.HTTPPort
		if port == 80 {
			return fmt.Sprintf("http://%s", host), nil
		}
		return fmt.Sprintf("http://%s:%d", host, port), nil
	}

	// Option 2: Parse docker port mapping
	port, err := getContainerHostPort(containerName)
	if err != nil {
		return "", err
	}
	return fmt.Sprintf("http://localhost:%d", port), nil
}

// hostnameForContainer converts a container name to a valid hostname using the configured domain
func hostnameForContainer(name, hostname string) string {
	base := strings.ToLower(strings.TrimSpace(name))
	base = strings.ReplaceAll(base, "_", "-")
	re := regexp.MustCompile(`[^a-z0-9-]`)
	base = re.ReplaceAllString(base, "-")
	base = strings.Trim(base, "-.")
	if base == "" {
		base = "dv"
	}
	if hostname == "" {
		hostname = "dv.localhost"
	}
	return base + "." + hostname
}

// getContainerHostPort extracts the published host port from a running container
func getContainerHostPort(containerName string) (int, error) {
	// Use docker port command to get the mapping
	cmd := exec.Command("docker", "port", containerName)
	out, err := cmd.Output()
	if err != nil {
		return 0, fmt.Errorf("get container port: %w", err)
	}

	// Parse output like "3000/tcp -> 0.0.0.0:3001"
	for _, line := range strings.Split(string(out), "\n") {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		// Find the host port after the last colon
		arrowIdx := strings.Index(line, "->")
		if arrowIdx == -1 {
			continue
		}
		right := strings.TrimSpace(line[arrowIdx+2:])
		colonIdx := strings.LastIndex(right, ":")
		if colonIdx == -1 {
			continue
		}
		portStr := right[colonIdx+1:]
		port, err := strconv.Atoi(portStr)
		if err == nil && port > 0 {
			return port, nil
		}
	}

	return 0, fmt.Errorf("no published port found for container %s", containerName)
}

package cli

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	textarea "charm.land/bubbles/v2/textarea"
	tea "charm.land/bubbletea/v2"
	"github.com/spf13/cobra"

	"dv/internal/config"
	"dv/internal/docker"
	"dv/internal/paste"
	"dv/internal/xdg"
)

// runAgentCmd implements `dv run-agent` (alias: `ra`).
// Usage:
//
//	dv ra <agent> [prompt_file|prompt words...]
//	dv ra <agent> -- [raw agent args...]
//
// If no prompt/args provided, an editor is opened to enter a multiline prompt.
// Prompt files are read from ~/.config/dv/prompts/ and autocompleted.
var runAgentCmd = &cobra.Command{
	Use:     "run-agent [--name NAME] AGENT [PROMPT_FILE|-- ARGS...|PROMPT ...]",
	Aliases: []string{"ra"},
	Short:   "Run an AI agent inside the container with a prompt or prompt file",
	Args:    cobra.MinimumNArgs(1),
	ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
		// First arg: agent name completion
		if len(args) == 0 {
			var cfg config.Config
			if configDir, err := xdg.ConfigDir(); err == nil {
				cfg, _ = config.LoadOrCreate(configDir)
			}
			var out []string
			pref := strings.ToLower(strings.TrimSpace(toComplete))
			for _, name := range agentCompletionNames(cfg) {
				if pref == "" || strings.HasPrefix(name, pref) {
					out = append(out, name)
				}
			}
			return out, cobra.ShellCompDirectiveNoFileComp
		}

		// Second arg: prompt file completion
		if len(args) == 1 {
			// If the user appears to be typing a filesystem path, defer to the shell's default
			// file completion so regular files can be selected as prompts.
			if strings.HasPrefix(toComplete, "./") || strings.HasPrefix(toComplete, "../") || strings.HasPrefix(toComplete, "/") || strings.Contains(toComplete, string(os.PathSeparator)) {
				return nil, cobra.ShellCompDirectiveDefault
			}

			configDir, err := xdg.ConfigDir()
			if err != nil {
				return nil, cobra.ShellCompDirectiveNoFileComp
			}

			promptsDir := filepath.Join(configDir, "prompts")
			entries, err := os.ReadDir(promptsDir)
			if err != nil {
				return nil, cobra.ShellCompDirectiveNoFileComp
			}

			var suggestions []string
			for _, entry := range entries {
				if !entry.IsDir() {
					suggestions = append(suggestions, entry.Name())
				}
			}

			// Filter by prefix
			var out []string
			pref := strings.ToLower(strings.TrimSpace(toComplete))
			for _, s := range suggestions {
				if pref == "" || strings.HasPrefix(strings.ToLower(s), pref) {
					out = append(out, s)
				}
			}
			return out, cobra.ShellCompDirectiveNoFileComp
		}

		// No completion for additional args
		return nil, cobra.ShellCompDirectiveNoFileComp
	},
	RunE: func(cmd *cobra.Command, args []string) error {
		configDir, err := xdg.ConfigDir()
		if err != nil {
			return err
		}
		cfg, err := config.LoadOrCreate(configDir)
		if err != nil {
			return err
		}

		name, _ := cmd.Flags().GetString("name")
		if name == "" {
			name = currentAgentName(cfg)
		}

		// Ensure container exists and is running (match behavior of `enter`)
		if !docker.Exists(name) {
			fmt.Fprintf(cmd.OutOrStdout(), "Container '%s' does not exist. Run 'dv start' first.\n", name)
			return nil
		}
		if !docker.Running(name) {
			fmt.Fprintf(cmd.OutOrStdout(), "Starting container '%s'...\n", name)
			if err := startContainerWithPostStartHook(cmd, cfg, configDir, name, cmd.Name()); err != nil {
				return err
			}
		}

		// Resolve workdir from image associated with container
		imgName := cfg.ContainerImages[name]
		var imgCfg config.ImageConfig
		if imgName != "" {
			imgCfg = cfg.Images[imgName]
		} else {
			_, imgCfg, err = resolveImage(cfg, "")
			if err != nil {
				return err
			}
		}
		workdir := config.EffectiveWorkdir(cfg, imgCfg, name)

		// Parse args: first token is the agent name (resolve aliases, returns lowercase)
		agent := resolveAgentAliasWithConfig(cfg, args[0])

		// Copy configured files (auth, etc.) into the container as in `enter`,
		// but scoped to the requested agent when configured.
		copyConfiguredFiles(cmd, cfg, name, workdir, agent)

		envs := buildAgentEnv(cfg, agent)

		rawArgs := []string{}
		rest := args[1:]

		// If user provided "--" treat everything after as raw agent args (no prompt wrapping).
		// Cobra strips the literal "--" from args, so rely on ArgsLenAtDash to find the split.
		if dash := cmd.ArgsLenAtDash(); dash >= 0 {
			if dash < len(args) {
				rawArgs = append(rawArgs, args[dash:]...)
			}
			if dash > 1 {
				rest = args[1:dash]
			} else {
				rest = []string{}
			}
		} else if len(rest) > 0 {
			// Fallback: honor an explicit "--" if flag parsing was disabled in the future.
			for i, a := range rest {
				if a == "--" {
					rawArgs = append(rawArgs, rest[i+1:]...)
					rest = rest[:i]
					break
				}
			}
		}

		// Check if the first argument after agent is a prompt file
		var promptFromFile string
		if len(rest) > 0 {
			firstArg := rest[0]
			// 1) Prefer an actual host filesystem path if it exists (supports relative/absolute)
			hostPath := expandHostPath(firstArg)
			if st, err := os.Stat(hostPath); err == nil && st.Mode().IsRegular() {
				if content, err2 := os.ReadFile(hostPath); err2 == nil {
					promptFromFile = strings.TrimSpace(string(content))
					rest = rest[1:]
				}
			} else {
				// 2) Fallback to a named prompt under ~/.config/dv/prompts
				promptsDir := filepath.Join(configDir, "prompts")
				promptFilePath := filepath.Join(promptsDir, firstArg)
				if st2, err3 := os.Stat(promptFilePath); err3 == nil && st2.Mode().IsRegular() {
					if content, err4 := os.ReadFile(promptFilePath); err4 == nil {
						promptFromFile = strings.TrimSpace(string(content))
						rest = rest[1:]
					}
				}
			}
		}

		// Build the argv to run inside the container using internal rules.
		var argv []string
		switch {
		case len(rawArgs) > 0:
			argv = buildAgentRawWithConfig(cfg, agent, rawArgs)
			// If this is a pure help request, capture output via non-TTY exec
			if isHelpArgs(rawArgs) {
				shellCmd := withUserPaths(shellJoin(argv))
				out, err := docker.ExecOutput(name, workdir, envs, []string{"bash", "-lc", shellCmd})
				if err != nil {
					fmt.Fprint(cmd.ErrOrStderr(), out)
					return err
				}
				fmt.Fprint(cmd.OutOrStdout(), out)
				return nil
			}
		case promptFromFile != "":
			// Prompt from file -> construct one-shot invocation with implicit bypass flags
			argv = buildAgentArgsWithConfig(cfg, agent, promptFromFile)
		case len(rest) == 0:
			// No prompt provided -> run interactively with implicit bypass flags
			argv = buildAgentInteractiveWithConfig(cfg, agent)
		default:
			// Prompt provided -> construct one-shot invocation with implicit bypass flags
			prompt := strings.Join(rest, " ")
			argv = buildAgentArgsWithConfig(cfg, agent, prompt)
		}

		// Execute inside container through a login shell to pick up PATH/rc files
		shellCmd := withUserPaths(shellJoin(argv))

		// Check if paste support is enabled
		pasteEnabled, _ := cmd.Flags().GetBool("paste")
		if pasteEnabled {
			return paste.ExecWithPaste(paste.DockerExecConfig{
				ContainerName: name,
				Workdir:       workdir,
				Envs:          envs,
				Argv:          []string{"bash", "-lc", shellCmd},
				User:          "discourse",
			})
		}
		return docker.ExecInteractive(name, workdir, envs, []string{"bash", "-lc", shellCmd})
	},
}

// collectPromptInteractive opens $EDITOR for a multiline prompt; falls back to terminal input if needed.
func collectPromptInteractive(cmd *cobra.Command) (string, error) {
	// Use a small Bubble Tea textarea for multiline prompt collection
	m := newPromptModel()
	p := tea.NewProgram(m)
	final, err := p.Run()
	if err != nil {
		return "", err
	}
	pm, ok := final.(promptModel)
	if !ok {
		return "", fmt.Errorf("unexpected model type")
	}
	if pm.canceled {
		return "", nil
	}
	return strings.TrimSpace(pm.ta.Value()), nil
}

func buildAgentEnv(cfg config.Config, agent string) docker.Envs {
	envs := collectEnvPassthrough(cfg)

	if rule, ok := agentRules[agent]; ok {
		envs = append(envs, rule.env...)
	}
	if custom, ok := customAgentConfig(cfg, agent); ok {
		envs = append(envs, custom.Env...)
	}

	// Pass through terminal capability variables for proper color support
	if _, ok := os.LookupEnv("TERM"); ok {
		envs = append(envs, "TERM")
	}
	if _, ok := os.LookupEnv("COLORTERM"); ok {
		envs = append(envs, "COLORTERM")
	}

	// Ensure a sane runtime environment for discourse user
	envs = append(envs,
		"HOME=/home/discourse",
		"USER=discourse",
		"SHELL=/bin/bash",
	)
	return envs
}

// buildAgentArgs uses internal, hard-coded rules per agent to construct argv.
// If the agent is unknown, falls back to positional prompt.
func buildAgentArgs(agent string, prompt string) []string {
	return buildAgentArgsWithConfig(config.Config{}, agent, prompt)
}

func buildAgentArgsWithConfig(cfg config.Config, agent string, prompt string) []string {
	if custom, ok := customAgentConfig(cfg, agent); ok {
		if rule, isBuiltin := agentRules[strings.ToLower(agent)]; isBuiltin && isDefaultsOnlyConfig(custom) {
			base := rule.withPrompt(prompt)
			defaults := rule.defaults
			if custom.Defaults != nil {
				defaults = *custom.Defaults
			}
			if len(defaults) > 0 {
				base = injectDefaults(base, defaults)
			}
			return base
		}
		return buildCustomAgentArgs(agent, custom, prompt)
	}
	if rule, ok := agentRules[strings.ToLower(agent)]; ok {
		base := rule.withPrompt(prompt)
		if len(rule.defaults) > 0 {
			base = injectDefaults(base, rule.defaults)
		}
		return base
	}
	return []string{agent, prompt}
}

func buildAgentInteractive(agent string) []string {
	return buildAgentInteractiveWithConfig(config.Config{}, agent)
}

func buildAgentInteractiveWithConfig(cfg config.Config, agent string) []string {
	if custom, ok := customAgentConfig(cfg, agent); ok {
		if rule, isBuiltin := agentRules[strings.ToLower(agent)]; isBuiltin && isDefaultsOnlyConfig(custom) {
			baseBuilder := rule.withoutPrompt
			if baseBuilder == nil {
				baseBuilder = rule.interactive
			}
			base := baseBuilder()
			defaults := rule.defaults
			if custom.Defaults != nil {
				defaults = *custom.Defaults
			}
			if len(defaults) > 0 {
				base = injectDefaults(base, defaults)
			}
			return base
		}
		cmd := custom.Command
		if strings.TrimSpace(cmd) == "" {
			cmd = agent
		}
		argv := append([]string{cmd}, custom.Args...)
		argv = append(argv, custom.InteractiveArgs...)
		return argv
	}
	if rule, ok := agentRules[strings.ToLower(agent)]; ok {
		baseBuilder := rule.withoutPrompt
		if baseBuilder == nil {
			baseBuilder = rule.interactive
		}
		base := baseBuilder()
		if len(rule.defaults) > 0 {
			base = injectDefaults(base, rule.defaults)
		}
		return base
	}
	return []string{agent}
}

func buildCustomAgentArgs(agent string, custom config.AgentConfig, prompt string) []string {
	cmd := strings.TrimSpace(custom.Command)
	if cmd == "" {
		cmd = agent
	}
	argv := append([]string{cmd}, custom.Args...)
	argv = append(argv, custom.PromptArgs...)
	argv = append(argv, prompt)
	return argv
}

func buildAgentRawWithConfig(cfg config.Config, agent string, rawArgs []string) []string {
	if custom, ok := customAgentConfig(cfg, agent); ok {
		cmd := strings.TrimSpace(custom.Command)
		if cmd == "" {
			cmd = agent
		}
		argv := append([]string{cmd}, custom.Args...)
		argv = append(argv, rawArgs...)
		return argv
	}
	return append([]string{agent}, rawArgs...)
}

func injectDefaults(argv []string, defaults []string) []string {
	if len(argv) == 0 || len(defaults) == 0 {
		return argv
	}
	out := make([]string, 0, len(argv)+len(defaults))
	out = append(out, argv[0])
	out = append(out, defaults...)
	out = append(out, argv[1:]...)
	return out
}

