// agentAliasMap maps aliases to canonical agent names (precomputed at init).
var agentAliasMap map[string]string

func init() {
	agentAliasMap = make(map[string]string)
	for canonical, rule := range agentRules {
		// Map canonical name to itself
		if existing, ok := agentAliasMap[canonical]; ok {
			panic("agent name collision: " + canonical + " already mapped to " + existing)
		}
		agentAliasMap[canonical] = canonical

		// Map aliases to canonical
		for _, alias := range rule.aliases {
			aliasLower := strings.ToLower(alias)
			if existing, ok := agentAliasMap[aliasLower]; ok {
				panic("agent alias collision: " + aliasLower + " already mapped to " + existing)
			}
			agentAliasMap[aliasLower] = canonical
		}
	}
}

// resolveAgentAlias returns the canonical agent name for a given alias (or the name itself).
func resolveAgentAlias(name string) string {
	lower := strings.ToLower(name)
	if canonical, ok := agentAliasMap[lower]; ok {
		return canonical
	}
	return lower
}

func resolveAgentAliasWithConfig(cfg config.Config, name string) string {
	lower := strings.ToLower(strings.TrimSpace(name))
	for _, customName := range sortedCustomAgentNames(cfg) {
		custom := cfg.Agents[customName]
		canonical := strings.ToLower(strings.TrimSpace(customName))
		if lower == canonical {
			return canonical
		}
		for _, alias := range custom.Aliases {
			if lower == strings.ToLower(strings.TrimSpace(alias)) {
				return canonical
			}
		}
	}
	if canonical, ok := agentAliasMap[lower]; ok {
		return canonical
	}
	return lower
}

func agentCompletionNames(cfg config.Config) []string {
	names := make(map[string]struct{}, len(agentAliasMap)+len(cfg.Agents))
	for name := range agentAliasMap {
		names[name] = struct{}{}
	}
	for _, customName := range sortedCustomAgentNames(cfg) {
		custom := cfg.Agents[customName]
		name := strings.ToLower(strings.TrimSpace(customName))
		if name == "" {
			continue
		}
		names[name] = struct{}{}
		for _, alias := range custom.Aliases {
			alias = strings.ToLower(strings.TrimSpace(alias))
			if alias != "" {
				names[alias] = struct{}{}
			}
		}
	}
	out := make([]string, 0, len(names))
	for name := range names {
		out = append(out, name)
	}
	sort.Strings(out)
	return out
}

// isDefaultsOnlyConfig reports whether a config entry only overrides defaults,
// with no Command/Args/PromptArgs/InteractiveArgs that would constitute a full
// custom agent definition. Such entries are applied on top of the built-in rule
// rather than replacing it entirely.
func isDefaultsOnlyConfig(c config.AgentConfig) bool {
	return c.Command == "" && len(c.Args) == 0 && len(c.PromptArgs) == 0 && len(c.InteractiveArgs) == 0
}

func customAgentConfig(cfg config.Config, agent string) (config.AgentConfig, bool) {
	agent = strings.ToLower(strings.TrimSpace(agent))
	for _, name := range sortedCustomAgentNames(cfg) {
		custom := cfg.Agents[name]
		if strings.ToLower(strings.TrimSpace(name)) == agent {
			return custom, true
		}
	}
	return config.AgentConfig{}, false
}

func sortedCustomAgentNames(cfg config.Config) []string {
	names := make([]string, 0, len(cfg.Agents))
	for name := range cfg.Agents {
		names = append(names, name)
	}
	sort.Slice(names, func(i, j int) bool {
		return strings.ToLower(strings.TrimSpace(names[i])) < strings.ToLower(strings.TrimSpace(names[j]))
	})
	return names
}

// shellJoin and shellQuote are now in shared.go

// withUserPaths prefixes a shell command with PATH extensions for common user-level bin dirs.
func withUserPaths(cmd string) string {
	prefix := "export PATH=\"$HOME/.local/bin:$HOME/bin:$HOME/.npm-global/bin:$HOME/.cargo/bin:$HOME/.grok/bin:$PATH\"; "
	return prefix + cmd
}

// ---- Minimal TUI for multiline prompt entry ----

type promptModel struct {
	ta       textarea.Model
	canceled bool
	width    int
	height   int
}

func newPromptModel() promptModel {
	ta := textarea.New()
	ta.Prompt = ""
	ta.Placeholder = "Type your prompt..."
	ta.ShowLineNumbers = false
	ta.Focus()
	w, h, ok := measureTerminal()
	if !ok || w <= 0 {
		w = 80
	}
	if !ok || h <= 0 {
		h = 24
	}
	pad := 6
	tw := w - pad
	if tw < 20 {
		tw = 20
	}
	th := h - pad
	if th > 20 {
		th = 20
	}
	ta.SetWidth(tw)
	ta.SetHeight(th)
	return promptModel{ta: ta, width: w, height: h}
}

func (m promptModel) Init() tea.Cmd { return nil }

func (m promptModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch t := msg.(type) {
	case tea.KeyPressMsg:
		switch t.String() {
		case "esc":
			m.canceled = true
			return m, tea.Quit
		case "ctrl+d", "ctrl+s":
			// Submit
			return m, tea.Quit
		}
	}
	var cmd tea.Cmd
	m.ta, cmd = m.ta.Update(msg)
	return m, cmd
}

func (m promptModel) View() tea.View {
	hint := "Ctrl+D to run ? Esc to cancel"
	box := lipBox(m.ta.View()+"\n"+hint, m.width, m.height)
	view := tea.NewView(box)
	view.AltScreen = true
	return view
}

func lipBox(content string, termW, termH int) string {
	// Simple centered box without importing lipgloss here; reuse width sensibly.
	// Just return content; surrounding TUI already uses alt screen.
	return content
}

// isHelpArgs returns true when args are a simple help request like --help or -h
func isHelpArgs(args []string) bool {
	if len(args) == 1 {
		a := args[0]
		return a == "--help" || a == "-h" || a == "help"
	}
	return false
}

