	if err != nil {
		t.Fatal(err)
	}
	cfg := config.Default()
	cfg.LocalProxy.Hostname = "dev.home.arpa"
	cfg.HostnameRemovals = map[string][]string{"forum": {"customers.dev.home.arpa"}}
	if err := config.Save(dir, cfg); err != nil {
