	cmd := &cobra.Command{}
	cmd.Flags().String("hostname", "", "")
	if err := cmd.Flags().Set("hostname", "other.home.arpa"); err != nil {
		t.Fatal(err)
	}
	if err := configLocalProxyCmd.RunE(cmd, nil); err == nil || !strings.Contains(err.Error(), "pending hostname removals") {
		t.Fatalf("error: %v", err)
	}
}

