func TestResolvedContainerTargetDiscourseWorkdir(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name    string
		image   config.ImageConfig
		want    string
		wantErr bool
	}{
		{name: "configured", image: config.ImageConfig{Kind: "discourse", Workdir: "/srv/discourse"}, want: "/srv/discourse"},
		{name: "default", image: config.ImageConfig{Kind: "discourse"}, want: "/var/www/discourse"},
		{name: "custom image", image: config.ImageConfig{Kind: "custom", Workdir: "/workspace"}, wantErr: true},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			t.Parallel()
			got, err := (resolvedContainerTarget{
				image:            test.image,
				effectiveWorkdir: "/custom/workspace-that-is-not-rails",
			}).discourseWorkdir()
			if test.wantErr {
				if err == nil {
					t.Fatalf("expected error, got workdir %q", got)
				}
				return
			}
			if err != nil {
				t.Fatal(err)
			}
			if got != test.want {
				t.Fatalf("got workdir %q, want %q", got, test.want)
			}
		})
	}
}

package cli

import (
	"context"
	"errors"
	"testing"

	"dv/internal/config"
)

func TestCollectContainerInventoryUsesOwnershipPrecedence(t *testing.T) {
	cfg := config.Default()
	cfg.LabelOverrides = map[string]map[string]string{}
	cfg.ContainerImages["mapped"] = "discourse"
	cfg.ContainerImages["mapped-elsewhere"] = "custom"
	cfg.LabelOverrides["overridden"] = map[string]string{
		"com.dv.owner":      "dv",
		"com.dv.image-name": "discourse",
	}
	image := cfg.Images["discourse"]
	query := func(context.Context) (string, error) {
		return "" +
			"mapped\tforeign:tag\tExited (0) 2 hours ago\t\t\t2026-07-27 10:00:00 +0000 UTC\n" +
			"labelled\tforeign:tag\tUp 1 hour\t\tcom.dv.owner=dv,com.dv.image-name=discourse\t2026-07-28 10:00:00 +0000 UTC\n" +
			"overridden\tforeign:tag\tCreated 3 hours ago\t\t\t2026-07-26 10:00:00 +0000 UTC\n" +
			"legacy\tai_agent\tUp 5 minutes\t0.0.0.0:3001->3000/tcp\t\t2026-07-29 10:00:00 +0000 UTC\n" +
			"mapped-elsewhere\tai_agent\tUp 2 minutes\t\t\t2026-07-29 10:30:00 +0000 UTC\n" +
			"unrelated\tforeign:tag\tUp 1 minute\t\t\t2026-07-29 11:00:00 +0000 UTC\n", nil
	}

	records, err := collectContainerInventory(context.Background(), cfg, "discourse", image, "labelled", query)
	if err != nil {
		t.Fatal(err)
	}
	if len(records) != 4 {
		t.Fatalf("got %d records, want 4: %#v", len(records), records)
	}
	seen := map[string]containerInventoryRecord{}
	for _, record := range records {
		seen[record.name] = record
	}
	for _, name := range []string{"mapped", "labelled", "overridden", "legacy"} {
		if _, ok := seen[name]; !ok {
			t.Errorf("missing %s", name)
		}
	}
	if _, ok := seen["unrelated"]; ok {
		t.Error("unrelated container was included")
	}
	if _, ok := seen["mapped-elsewhere"]; ok {
		t.Error("explicit mapping to another image was overridden by tag fallback")
	}
	if !seen["labelled"].selected {
		t.Error("selected container was not marked")
	}
	if got := seen["legacy"].urls; len(got) != 1 || got[0] != "http://localhost:3001" {
		t.Fatalf("legacy URLs = %#v", got)
	}
}

func TestCollectContainerInventoryReturnsDockerFailure(t *testing.T) {
	want := errors.New("daemon unavailable")
	_, err := collectContainerInventory(context.Background(), config.Default(), "discourse", config.Default().Images["discourse"], "", func(context.Context) (string, error) {
		return "", want
	})
	if !errors.Is(err, want) {
		t.Fatalf("error = %v, want %v", err, want)
	}
}

package cli

import (
	"bytes"
	"os"
	"path/filepath"
	"testing"
)

func TestApplyExtractStatusHandlesRename(t *testing.T) {
	containerDir := t.TempDir()
	localRepo := t.TempDir()

	oldPath := filepath.Join(localRepo, "old.txt")
	if err := os.WriteFile(oldPath, []byte("old"), 0o644); err != nil {
		t.Fatal(err)
	}
	newSrc := filepath.Join(containerDir, "new.txt")
	if err := os.WriteFile(newSrc, []byte("new"), 0o644); err != nil {
		t.Fatal(err)
	}

	origCopy := extractCopyFromContainer
	t.Cleanup(func() {
		extractCopyFromContainer = origCopy
	})
	extractCopyFromContainer = func(_ string, srcInContainer, dstOnHost string) error {
		return copyFile(srcInContainer, dstOnHost)
	}

	var logBuf bytes.Buffer
	changedCount, err := applyExtractStatus(&logBuf, "fake-container", containerDir, localRepo, "R  new.txt\x00old.txt\x00")
	if err != nil {
		t.Fatalf("applyExtractStatus failed: %v", err)
	}
	if changedCount != 1 {
		t.Fatalf("changedCount = %d, want 1", changedCount)
	}
	if _, err := os.Stat(oldPath); !os.IsNotExist(err) {
		t.Fatalf("old path still exists after rename, err=%v", err)
	}
	newDst := filepath.Join(localRepo, "new.txt")
	contents, err := os.ReadFile(newDst)
	if err != nil {
		t.Fatal(err)
	}
	if string(contents) != "new" {
		t.Fatalf("new file contents = %q, want %q", string(contents), "new")
	}
}

func TestParseStatusOutputPreservesSpacesAndRenameMarkers(t *testing.T) {
	newPath := " new  -> target "
	oldPath := "old -> name "
	spacedPath := " leading and trailing "
	out := "R  " + newPath + "\x00" + oldPath + "\x00?? " + spacedPath + "\x00"

	entries := parseStatusOutput(out)
	if len(entries) != 2 {
		t.Fatalf("len(entries) = %d, want 2", len(entries))
	}

	if entries[0].staged != 'R' || entries[0].unstaged != ' ' {
		t.Fatalf("rename entry status = %q%q, want R<space>", entries[0].staged, entries[0].unstaged)
	}
	if entries[0].path != newPath {
		t.Fatalf("rename new path = %q, want %q", entries[0].path, newPath)
	}
	if entries[0].oldPath != oldPath {
		t.Fatalf("rename old path = %q, want %q", entries[0].oldPath, oldPath)
	}

	if entries[1].staged != '?' || entries[1].unstaged != '?' {
		t.Fatalf("untracked entry status = %q%q, want ??", entries[1].staged, entries[1].unstaged)
	}
	if entries[1].path != spacedPath {
		t.Fatalf("untracked path = %q, want %q", entries[1].path, spacedPath)
	}
}

package discourse

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestEnsureAIBotDebuggingAllowedGroups(t *testing.T) {
	tests := []struct {
		name      string
		current   interface{}
		wantValue string
		wantPut   bool
	}{
		{
			name:      "empty setting gets trust level zero and staff",
			current:   "",
			wantValue: "10|3",
			wantPut:   true,
		},
		{
			name:      "existing groups are preserved when staff is appended",
			current:   "42|10",
			wantValue: "42|10|3",
			wantPut:   true,
		},
		{
			name:    "staff is not duplicated",
			current: "42|3",
			wantPut: false,
		},
		{
			name:      "legacy trust level name is converted to group IDs",
			current:   "trust_level_0",
			wantValue: "10|3",
			wantPut:   true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			putCount := 0
			var gotValue interface{}

			server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				switch {
				case r.Method == http.MethodGet && r.URL.Path == "/admin/site_settings.json":
					if got := r.URL.Query().Get("filter"); got != "ai_bot_debugging_allowed_groups" {
						t.Errorf("filter = %q, want ai_bot_debugging_allowed_groups", got)
					}
					w.Header().Set("Content-Type", "application/json")
					if err := json.NewEncoder(w).Encode(SiteSettingsResponse{SiteSettings: []SiteSetting{{
						Setting: "ai_bot_debugging_allowed_groups",
						Value:   tt.current,
					}}}); err != nil {
						t.Errorf("encode GET response: %v", err)
					}
				case r.Method == http.MethodPut && r.URL.Path == "/admin/site_settings/ai_bot_debugging_allowed_groups.json":
					putCount++
					var payload map[string]interface{}
					if err := json.NewDecoder(r.Body).Decode(&payload); err != nil {
						t.Errorf("decode PUT request: %v", err)
					}
					gotValue = payload["ai_bot_debugging_allowed_groups"]
					w.WriteHeader(http.StatusNoContent)
				default:
					http.Error(w, "unexpected request", http.StatusNotFound)
				}
			}))
			defer server.Close()

			client := NewClientWithURL("test", server.URL, "", nil, false)
			client.APIKey = "test-key"
			client.APIUsername = "system"
			if err := client.EnsureAIBotDebuggingAllowedGroups(); err != nil {
				t.Fatalf("EnsureAIBotDebuggingAllowedGroups returned error: %v", err)
			}

			if tt.wantPut {
				if putCount != 1 {
					t.Fatalf("PUT count = %d, want 1", putCount)
				}
				if gotValue != tt.wantValue {
					t.Errorf("setting value = %#v, want %q", gotValue, tt.wantValue)
				}
			} else if putCount != 0 {
				t.Errorf("PUT count = %d, want 0", putCount)
			}
		})
	}
}
